begin;
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,email text unique not null,full_name text,role text not null default 'user' check(role in('user','admin')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.colleges (id uuid primary key default gen_random_uuid(),name text not null,short_description text,description text,location text,website_url text,image_url text,is_active boolean not null default true,display_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.college_courses (id uuid primary key default gen_random_uuid(),college_id uuid not null references public.colleges(id) on delete cascade,name text not null,description text,duration text,degree_type text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.student_requests (id uuid primary key default gen_random_uuid(),student_name text not null,college_name text not null,course_name text not null,phone_number text not null,email text,country text,city text,education_level text,message text,status text not null default 'pending' check(status in('pending','reviewed','contacted','processing','completed','rejected')),admin_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.site_settings (id uuid primary key default gen_random_uuid(),setting_key text unique not null,setting_value jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now();return new;end $$;
do $$ declare t text;begin foreach t in array array['profiles','colleges','college_courses','student_requests','site_settings'] loop execute format('drop trigger if exists set_%I_updated_at on public.%I',t,t);execute format('create trigger set_%I_updated_at before update on public.%I for each row execute function public.set_updated_at()',t,t);end loop;end $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
revoke all on function public.is_admin() from public;grant execute on function public.is_admin() to authenticated;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name,role) values(new.id,new.email,nullif(new.raw_user_meta_data->>'full_name',''),'user') on conflict(id) do nothing;return new;end $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security;alter table public.colleges enable row level security;alter table public.college_courses enable row level security;alter table public.student_requests enable row level security;alter table public.site_settings enable row level security;
do $$ declare p text;t text;begin for p,t in select * from(values ('profiles_select_own','profiles'),('profiles_admin_select','profiles'),('profiles_admin_insert','profiles'),('profiles_admin_update','profiles'),('profiles_admin_delete','profiles'),('colleges_public_select','colleges'),('colleges_admin_select','colleges'),('colleges_admin_insert','colleges'),('colleges_admin_update','colleges'),('colleges_admin_delete','colleges'),('courses_public_select','college_courses'),('courses_admin_select','college_courses'),('courses_admin_insert','college_courses'),('courses_admin_update','college_courses'),('courses_admin_delete','college_courses'),('requests_public_insert','student_requests'),('requests_admin_select','student_requests'),('requests_admin_update','student_requests'),('requests_admin_delete','student_requests'),('settings_public_select','site_settings'),('settings_admin_select','site_settings'),('settings_admin_insert','site_settings'),('settings_admin_update','site_settings'),('settings_admin_delete','site_settings'))x(p,t) loop execute format('drop policy if exists %I on public.%I',p,t);end loop;end $$;
create policy profiles_select_own on public.profiles for select to authenticated using(id=auth.uid());create policy profiles_admin_select on public.profiles for select to authenticated using(public.is_admin());create policy profiles_admin_insert on public.profiles for insert to authenticated with check(public.is_admin());create policy profiles_admin_update on public.profiles for update to authenticated using(public.is_admin()) with check(public.is_admin());create policy profiles_admin_delete on public.profiles for delete to authenticated using(public.is_admin());
create policy colleges_public_select on public.colleges for select to anon,authenticated using(is_active=true);create policy colleges_admin_select on public.colleges for select to authenticated using(public.is_admin());create policy colleges_admin_insert on public.colleges for insert to authenticated with check(public.is_admin());create policy colleges_admin_update on public.colleges for update to authenticated using(public.is_admin()) with check(public.is_admin());create policy colleges_admin_delete on public.colleges for delete to authenticated using(public.is_admin());
create policy courses_public_select on public.college_courses for select to anon,authenticated using(exists(select 1 from public.colleges c where c.id=college_id and c.is_active));create policy courses_admin_select on public.college_courses for select to authenticated using(public.is_admin());create policy courses_admin_insert on public.college_courses for insert to authenticated with check(public.is_admin());create policy courses_admin_update on public.college_courses for update to authenticated using(public.is_admin()) with check(public.is_admin());create policy courses_admin_delete on public.college_courses for delete to authenticated using(public.is_admin());
create policy requests_public_insert on public.student_requests for insert to anon,authenticated with check(status='pending' and admin_notes is null);create policy requests_admin_select on public.student_requests for select to authenticated using(public.is_admin());create policy requests_admin_update on public.student_requests for update to authenticated using(public.is_admin()) with check(public.is_admin());create policy requests_admin_delete on public.student_requests for delete to authenticated using(public.is_admin());
create policy settings_public_select on public.site_settings for select to anon,authenticated using(setting_key like 'public.%');create policy settings_admin_select on public.site_settings for select to authenticated using(public.is_admin());create policy settings_admin_insert on public.site_settings for insert to authenticated with check(public.is_admin());create policy settings_admin_update on public.site_settings for update to authenticated using(public.is_admin()) with check(public.is_admin());create policy settings_admin_delete on public.site_settings for delete to authenticated using(public.is_admin());
insert into storage.buckets(id,name,public) values('college-images','college-images',true) on conflict(id) do update set public=true;
drop policy if exists college_images_public_read on storage.objects;drop policy if exists college_images_admin_insert on storage.objects;drop policy if exists college_images_admin_update on storage.objects;drop policy if exists college_images_admin_delete on storage.objects;
create policy college_images_public_read on storage.objects for select to public using(bucket_id='college-images');create policy college_images_admin_insert on storage.objects for insert to authenticated with check(bucket_id='college-images' and public.is_admin());create policy college_images_admin_update on storage.objects for update to authenticated using(bucket_id='college-images' and public.is_admin()) with check(bucket_id='college-images' and public.is_admin());create policy college_images_admin_delete on storage.objects for delete to authenticated using(bucket_id='college-images' and public.is_admin());
